const input=$json??{}; const event=input.event??input;
const dealId=event.deal_id??event.dealId, leadId=event.lead_id??event.leadId, propertyId=event.property_id??event.propertyId;
const status=String(event.status??event.delivery_status??'').toLowerCase();
const responseStatus=String(event.response_status??'').toLowerCase();
const dnc=Boolean(event.dnc??event.do_not_contact), blockers=Array.isArray(event.blockers)?event.blockers:[];
const attempts=Number(event.attempts??event.outreach_attempts??0), maxAttempts=Number(event.max_attempts??3);
const deliveredAt=event.delivered_at??event.delivery_timestamp;
const timeoutHours=Number(event.response_timeout_hours??24);
const timeoutAt=event.response_timeout_at??(deliveredAt?new Date(new Date(deliveredAt).getTime()+timeoutHours*3600000).toISOString():null);
const now=event.now??new Date().toISOString();
const responded=Boolean(event.inbound_response||event.seller_response||['seller_response','received','reply'].includes(responseStatus));
const timedOut=Boolean(event.response_timeout||event.timeout_due||(timeoutAt&&new Date(now).getTime()>=new Date(timeoutAt).getTime()));
const baseKey=event.idempotency_key??[dealId,leadId,propertyId,'seller-followup'].filter(Boolean).join(':');
const stateKey=baseKey+':response-state:'+attempts;
let route='WF-351',decision='waiting_for_seller_response';
if(dnc){route='WF-126';decision='dnc_hard_stop';}
else if(blockers.length){route='WF-126';decision='blocked';}
else if(!dealId||!leadId||!propertyId||!baseKey){route='WF-352';decision='identity_or_idempotency_missing';}
else if(responded){route='WF-342';decision='seller_response_received';}
else if(status==='failed'||status==='bounced'||status==='rejected'||status==='undeliverable'){route='WF-350';decision='delivery_failure';}
else if(timedOut&&attempts>=maxAttempts){route='WF-126';decision='human_review_max_attempts';}
else if(timedOut){route='WF-352';decision='seller_response_timeout_followup_due';}
else if(['delivered','sent','accepted'].includes(status)||deliveredAt){route='WF-351';decision='waiting_for_seller_response';}
else {route='WF-355';decision='awaiting_delivery_receipt';}
return [{json:{...event,workflow:'WF-356',decision,route,deal_id:dealId,lead_id:leadId,property_id:propertyId,attempts,max_attempts:maxAttempts,delivered_at:deliveredAt,response_timeout_at:timeoutAt,response_timeout_hours:timeoutHours,idempotency_key:baseKey,state_idempotency_key:stateKey,audit_event:'delivery_receipt_seller_response_timeout_reconciliation'}}];
